descriptor.controllerScript:
self.onInit = function () {
    var root = self.ctx.$container[0];
    var led = root.querySelector('.stw-led');
    var txt = root.querySelector('.stw-txt');

    function isTrue(v) { return v === true || v === 'true' || v === 1 || v === '1'; }
    function last(s) { var d = s.data; return (d && d.length) ? d[d.length - 1][1] : undefined; }

    function update() {
        var v = {};
        (self.ctx.data || []).forEach(function (s) { v[s.dataKey.label || s.dataKey.name] = last(s); });

        var st;
        if (v.active === undefined && v.run === undefined) { st = ['#9e9e9e', '…']; }          // no data yet
        else if (v.active !== undefined && !isTrue(v.active)) { st = ['#e74c3c', 'Offline']; }
        else if (!isTrue(v.run)) { st = ['#e74c3c', 'Leállítva']; }
        else if (isTrue(v.wrn)) { st = ['#f1c40f', 'Hiba']; }
        else { st = ['#2ecc71', 'Működés']; }

        led.style.background = st[0];
        txt.textContent = st[1];
    }

    self.onDataUpdated = update;
    update();
};

self.onDestroy = function () {};

